"""Weekly timesheet rows built from a list of shifts."""

from typing import Dict, List, Tuple

from hourglass.models import Shift


def check_shifts(shifts: List[Shift]) -> None:
    """ValueError for no shifts or a blank worker name."""
    if not shifts:
        raise ValueError("no shifts to report")
    for shift in shifts:
        if not shift.worker.strip():
            raise ValueError("shift has a blank worker")


def tally(shifts: List[Shift]) -> Dict[str, Tuple[int, int]]:
    """Shift count and total minutes per worker name."""
    totals = {}
    for shift in shifts:
        name = shift.worker.strip()
        count, mins = totals.get(name, (0, 0))
        totals[name] = (count + 1, mins + shift.span.minutes)
    return totals


def format_row(name: str, count: int, mins: int) -> str:
    noun = "shift" if count == 1 else "shifts"
    hours = f"{mins / 60:.1f}"
    return f"{name}: {count} {noun}, {hours} hours"


def timesheet_lines(shifts: List[Shift]) -> List[str]:
    """One line per worker, most hours first, then by name."""
    check_shifts(shifts)
    totals = tally(shifts)
    order = sorted(
        totals, key=lambda who: (-totals[who][1], who)
    )
    return [format_row(who, *totals[who]) for who in order]

