# owner: platform
import unittest

from hourglass.models import Shift, Span
from hourglass.timesheet import timesheet_lines


def make_shift(worker, start, end, day="mon"):
    return Shift(worker, day, Span(start, end))


class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        shifts = [
            make_shift("Ana", 480, 600),
            make_shift("Brisa", 480, 720),
            make_shift("Brisa", 480, 600, "tue")
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Brisa: 2 shifts, 6.0 hours",
                "Ana: 1 shift, 2.0 hours"
            ]
        )

    def test_one_decimal_place(self):
        lines = timesheet_lines([make_shift("Ana", 0, 100)])
        self.assertEqual(lines, ["Ana: 1 shift, 1.7 hours"])

    def test_ties_sorted_by_name(self):
        shifts = [
            make_shift("Zed", 0, 60),
            make_shift("Amy", 0, 60)
        ]
        lines = timesheet_lines(shifts)
        self.assertTrue(lines[0].startswith("Amy"))

    def test_empty_list(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker(self):
        shifts = [make_shift("Ana", 0, 60)]
        shifts.append(make_shift("  ", 0, 60))
        with self.assertRaises(ValueError):
            timesheet_lines(shifts)
